import { upperFirst } from 'lodash';

import {
  type AlertState,
  type DataTransformerConfig,
  type GrafanaTheme2,
  type ScopedVars,
  TransformerCategory,
} from '@grafana/data';
import { t } from '@grafana/i18n';
import { type CustomTransformerDefinition, SafeSerializableSceneObject, type VizPanel } from '@grafana/scenes';
import { type DataQuery } from '@grafana/schema';
import { isExpressionQuery } from 'app/features/expressions/guards';
import { getExpressionLabel, type ExpressionQuery } from 'app/features/expressions/types';

import { getAlertStateColor, getQueryEditorTypeConfig, QueryEditorType } from '../constants';

import { type PendingExpression, type PendingTransformation } from './QueryEditorContext';
import { type AlertRule, type Transformation } from './types';

export function getPanelScopedVars(panel: VizPanel): ScopedVars {
  return { __sceneObject: new SafeSerializableSceneObject(panel) };
}

export function getEditorType(
  card: DataQuery | Transformation | AlertRule | null,
  pendingExpression?: PendingExpression | null,
  pendingTransformation?: PendingTransformation | null
): QueryEditorType {
  if (pendingExpression) {
    return QueryEditorType.Expression;
  }

  if (pendingTransformation) {
    return QueryEditorType.Transformation;
  }

  if (!card) {
    // Default to query type if no card is provided
    return QueryEditorType.Query;
  }

  if ('alertId' in card) {
    return QueryEditorType.Alert;
  }

  if ('transformId' in card) {
    return QueryEditorType.Transformation;
  }

  if (isExpressionQuery(card)) {
    return QueryEditorType.Expression;
  }

  return QueryEditorType.Query;
}

/**
 * Section label for an expression card, e.g. "SQL Expression". Shared by the single-edit header and
 * the stacked editor so both render expression labels identically, matching the names on the
 * expression type picker cards.
 */
export function getExpressionSectionLabel(query: ExpressionQuery): string {
  // The fallback looks unreachable because `type` is typed as an enum member, but isExpressionQuery
  // accepts any query pointing at the __expr__ datasource without validating `type`, so an absent
  // or unrecognised type reaches here at runtime.
  const typeName = getExpressionLabel(query.type) ?? upperFirst(query.type);

  return t('query-editor-next.labels.expression-title', '{{type}} Expression', { type: typeName });
}

function isDataTransformerConfig(
  transformation: DataTransformerConfig | CustomTransformerDefinition | null
): transformation is DataTransformerConfig {
  // A CustomTransformerDefinition is an operator function or `{ operator, topic }`, so `id` is the
  // only discriminator. `refId` is not: a transformation config can carry a user-set one.
  return typeof transformation === 'object' && transformation !== null && 'id' in transformation;
}

/**
 * Filters an array of transformations to only include DataTransformerConfig items since
 * the UI does not support CustomTransformerDefinition items.
 * @param transformations - The array of transformations to filter.
 * @returns An array of DataTransformerConfig items.
 */
export const filterDataTransformerConfigs = (
  transformations: Array<DataTransformerConfig | CustomTransformerDefinition>
): DataTransformerConfig[] => {
  return transformations.filter((t): t is DataTransformerConfig => isDataTransformerConfig(t));
};

export function getTransformId(transformConfigId: string, index: number): string {
  return `${transformConfigId}-${index}`;
}

/**
 * Gets the border color for a query editor card based on its type.
 * For alerts, uses dynamic state-based color; otherwise uses static config color.
 *
 * @param theme - Grafana theme object
 * @param editorType - The type of editor (Query, Expression, Transformation, Alert)
 * @param alertState - Optional alert state (only used when editorType is Alert)
 * @returns The border color string
 */
export function getEditorBorderColor({
  theme,
  editorType,
  alertState,
  isError,
}: {
  theme: GrafanaTheme2;
  editorType: QueryEditorType;
  alertState?: AlertState | null;
  isError?: boolean;
}): string {
  if (isError) {
    return theme.colors.error.border;
  }

  if (editorType === QueryEditorType.Alert && alertState) {
    return getAlertStateColor(theme, alertState);
  }

  const typeConfig = getQueryEditorTypeConfig(theme);
  return typeConfig[editorType].color;
}

export function getHiddenMaskStyles(theme: GrafanaTheme2) {
  return {
    opacity: theme.isDark ? 0.6 : 0.7,
    filter: 'grayscale(0.8)',
  };
}

